            alert(`GoK Capitation posted!\nTotal: KES ${gokTotalReceived.toLocaleString()}\nSIMBA: KES ${gokSimbaAmount.toLocaleString()}\nGPA: KES ${gokGpaAmount.toLocaleString()}`);
